'use strict';
// Resonant synthesis, stereo room, and a bounded voice pool. No audio downloads.
class SoundEngine {
 constructor(){this.ctx=null;this.voices=new Set();this.lastNotes=[];this.capture=null;}
 start(){try{if(!this.ctx){const C=window.AudioContext||window.webkitAudioContext;this.ctx=new C();this.master=this.ctx.createGain();this.limit=this.ctx.createDynamicsCompressor();Object.assign(this.limit.threshold,{value:-20});this.limit.knee.value=18;this.limit.ratio.value=8;this.limit.attack.value=.004;this.limit.release.value=.22;this.master.connect(this.limit);this.limit.connect(this.ctx.destination);this.noise=this.ctx.createBuffer(1,Math.floor(this.ctx.sampleRate*.7),this.ctx.sampleRate);const d=this.noise.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=Math.random()*2-1;this.roomBuffer=this.ctx.createBuffer(2,Math.floor(this.ctx.sampleRate*2.8),this.ctx.sampleRate);for(let c=0;c<2;c++){const b=this.roomBuffer.getChannelData(c);for(let i=0;i<b.length;i++){const t=i/this.ctx.sampleRate;b[i]=t<.026?0:(Math.random()*2-1)*Math.pow(1-i/b.length,2.5)*.6;}}this.makeRoom();this.volume();}if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>toast('Tap again to enable sound.'));}catch{toast('Audio is unavailable here. Try Chrome or Edge.');}}
 makeRoom(){if(this.room)this.room.disconnect();if(this.roomTone)this.roomTone.disconnect();if(this.roomWet)this.roomWet.disconnect();this.room=this.ctx.createConvolver();this.room.buffer=this.roomBuffer;this.roomTone=this.ctx.createBiquadFilter();this.roomTone.type='lowpass';this.roomTone.frequency.value=4300;this.roomWet=this.ctx.createGain();this.room.connect(this.roomTone);this.roomTone.connect(this.roomWet);this.roomWet.connect(this.master);this.roomWet.gain.value=(settings.reverb??35)/100*.62;}
 volume(){if(!this.ctx)return;this.master.gain.setTargetAtTime(muted?0:settings.volume/100*.5,this.ctx.currentTime,.045);this.roomWet.gain.setTargetAtTime((settings.reverb??35)/100*.62,this.ctx.currentTime,.08);}
 note(index,duration=.7,kind=settings.sound,velocity=.6,pan=0,sustain=false){if(!this.ctx||muted||hidden)return null;const now=this.ctx.currentTime;this.lastNotes=this.lastNotes.filter(t=>now-t<.08);if(this.lastNotes.length>=20)return null;this.lastNotes.push(now);while(this.voices.size>=32)this.voices.values().next().value.stop();if(kind==='auto')kind='mallet';const ctx=this.ctx,env=ctx.createGain(),tone=ctx.createBiquadFilter(),panner=ctx.createStereoPanner();tone.type='lowpass';tone.frequency.value=kind==='warm'?1800:kind==='voice'?2200:kind==='pluck'?4400:6500;tone.Q.value=.45;panner.pan.value=clamp(pan,-.8,.8);tone.connect(env);env.connect(panner);panner.connect(this.master);panner.connect(this.room);const length=clamp(duration*(settings.sustain??1),.12,5);const profiles={mallet:[[1,1,1],[2.756,.28,.3],[5.404,.12,.14]],piano:[[1,1,1],[2,.34,.65],[3,.2,.34],[4.01,.09,.22],[5,.05,.15]],pluck:[[1,1,1],[2,.45,.65],[3,.28,.4],[4,.15,.25],[5,.08,.17],[6,.03,.1]],bell:[[1,1,1],[2.01,.34,.8],[2.756,.16,.55],[4.01,.11,.3]],warm:[[.998,1,1],[1.002,.8,1],[2,.12,1]],voice:[[1,1,1],[2,.3,1],[3,.24,1],[4,.06,1]]};const partials=profiles[kind]||profiles.mallet,oscs=[];let stopped=false;const peak=clamp(velocity,.02,.85)*.52;for(const[ratio,gain,decay]of partials){const o=ctx.createOscillator(),a=ctx.createGain();o.type=kind==='warm'?'triangle':'sine';o.frequency.value=freq(index)*ratio;a.gain.setValueAtTime(gain/1.8,now);if(!sustain)a.gain.exponentialRampToValueAtTime(.001,now+length*decay);else if(kind!=='warm'&&kind!=='voice')a.gain.exponentialRampToValueAtTime(Math.max(.02,gain*.15),now+.9*decay);o.connect(a);a.connect(tone);o.start(now);oscs.push({o,a,ratio});}const attack=kind==='warm'?.1:kind==='voice'?.06:.009;env.gain.setValueAtTime(.0001,now);env.gain.exponentialRampToValueAtTime(peak,now+attack);if(!sustain){env.gain.exponentialRampToValueAtTime(.0001,now+length+.12);oscs.forEach(({o})=>o.stop(now+length+.18));}let record=this.capture?.({type:'note',midi:typeof index==='object'?index.midi:noteMidi(index),duration:length,kind,velocity,pan,sustain});const closeRecord=()=>{if(record&&sustain)record.duration=Math.max(.1,elapsed-record.absoluteStart);};const voice={set:(i,bright=.5)=>{if(stopped)return;oscs.forEach(({o,ratio})=>o.frequency.setTargetAtTime(freq(i)*ratio,ctx.currentTime,.07));tone.frequency.setTargetAtTime(500+bright*5000,ctx.currentTime,.08);const midi=typeof i==='object'?i.midi:noteMidi(i);if(record&&record.midi!==midi){closeRecord();record=this.capture?.({type:'note',midi,duration:.5,kind,velocity,pan,sustain:true});}},stop:()=>{if(stopped)return;stopped=true;closeRecord();env.gain.cancelScheduledValues(ctx.currentTime);env.gain.setTargetAtTime(.0001,ctx.currentTime,kind==='warm'?.09:.04);oscs.forEach(({o})=>{try{o.stop(ctx.currentTime+.5);}catch{}});this.voices.delete(voice);}};oscs[0].o.onended=()=>{this.voices.delete(voice);env.disconnect();tone.disconnect();panner.disconnect();oscs.forEach(({o,a})=>{o.disconnect();a.disconnect();});};this.voices.add(voice);return voice;}
 drum(type=0,velocity=.65,pan=0){if(!this.ctx||muted||hidden)return;while(this.voices.size>=32)this.voices.values().next().value.stop();const ctx=this.ctx,now=ctx.currentTime,out=ctx.createGain(),panner=ctx.createStereoPanner(),nodes=[];panner.pan.value=clamp(pan,-.8,.8);out.connect(panner);panner.connect(this.master);panner.connect(this.room);const osc=(hz,end,gain,wave='sine')=>{const o=ctx.createOscillator(),a=ctx.createGain();o.type=wave;o.frequency.setValueAtTime(hz,now);o.frequency.exponentialRampToValueAtTime(end,now+.17);a.gain.value=gain;o.connect(a);a.connect(out);o.start(now);o.stop(now+.6);nodes.push(o,a);};type%=5;if(type===0){osc(135,42,.85);osc(220,80,.12);}else if(type===1){osc(270,140,.6);osc(425,310,.22);}else if(type===3){osc(720,700,.4);osc(1120,1100,.25);}else{const n=ctx.createBufferSource(),f=ctx.createBiquadFilter();n.buffer=this.noise;f.type=type===4?'highpass':'bandpass';f.frequency.value=type===4?5300:2000;f.Q.value=type===4?.5:.7;n.connect(f);f.connect(out);n.start(now);n.stop(now+.3);nodes.push(n,f);if(type===2)osc(175,145,.3);}out.gain.setValueAtTime(.0001,now);out.gain.linearRampToValueAtTime(velocity*.65,now+.003);out.gain.exponentialRampToValueAtTime(.0001,now+(type===0?.45:type===1?.3:type===4?.1:.18));this.capture?.({type:'drum',drum:type,duration:.4,velocity,pan});const voice={stop:()=>{out.gain.setTargetAtTime(.0001,ctx.currentTime,.02);this.voices.delete(voice);}};this.voices.add(voice);nodes[0].onended=()=>{this.voices.delete(voice);for(const n of nodes)n.disconnect();out.disconnect();panner.disconnect();};}
 stop(){for(const v of [...this.voices])v.stop();if(this.ctx)this.makeRoom();}
}
